import * as THREE from './vendor/three/three.module.js';
export function makeObject(kind='vase',wireframe=false){const g=new THREE.Group();const material=new THREE.MeshStandardMaterial({color:0x498ee8,metalness:.32,roughness:.33,side:THREE.DoubleSide,wireframe});if(kind==='vase'){const pos=[],norm=[],uv=[],idx=[];const rows=160,cols=120;for(let j=0;j<=rows;j++){const t=j/rows;const y=t*3.2-1.6;const base=.63+.35*Math.sin(t*Math.PI*1.25)+.19*Math.cos(t*Math.PI*2);for(let i=0;i<=cols;i++){const a=i/cols*Math.PI*2;const r=base+.065*Math.cos(a*12+t*4.8)+.009*Math.cos(t*Math.PI*160);pos.push(r*Math.cos(a),y,r*Math.sin(a));uv.push(i/cols,t);if(j<rows&&i<cols){const n=j*(cols+1)+i;idx.push(n,n+cols+1,n+1,n+1,n+cols+1,n+cols+2);}}}const geom=new THREE.BufferGeometry();geom.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));geom.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geom.setIndex(idx);geom.computeVertexNormals();g.add(new THREE.Mesh(geom,material));}else if(kind==='knot'){g.add(new THREE.Mesh(new THREE.TorusKnotGeometry(.85,.22,160,20,2,3),material));}else{const geo=new THREE.TorusGeometry(.92,.23,20,80,Math.PI);const arch=new THREE.Mesh(geo,material);arch.position.y=-.4;g.add(arch);for(const x of [-.92,.92]){const leg=new THREE.Mesh(new THREE.CylinderGeometry(.23,.23,.8,24),material);leg.position.set(x,-.8,0);g.add(leg);}}g.userData.material=material;return g;}
export function lighting(scene){scene.add(new THREE.HemisphereLight(0xc6e1ff,0x0b1a30,2.7));for(const [color,intensity,x,y,z] of [[0xe5f1ff,5,3,5,4],[0x226dff,6,-4,1,-2],[0x89caff,3,2,1,-4]]){const l=new THREE.DirectionalLight(color,intensity);l.position.set(x,y,z);scene.add(l);}}
export function thumbnail(kind){const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setSize(680,540);renderer.setClearColor(0x0d1625,1);const scene=new THREE.Scene();lighting(scene);const camera=new THREE.PerspectiveCamera(36,680/540,.1,50);camera.position.set(4,2.5,6);camera.lookAt(0,0,0);const model=makeObject(kind);scene.add(model);renderer.render(scene,camera);const url=renderer.domElement.toDataURL('image/png');model.traverse(o=>{o.geometry?.dispose();if(o.material)o.material.dispose()});renderer.dispose();renderer.forceContextLoss();return url;}
